"""
    Return unique items in a sequence ``seq`` preserving their original order.
    """
def ordered_unique(seq: Any) -> object {
    if not seq {
        return [];
    }
    uniques = [];
    for item in seq {
        if (item in uniques) {
            continue;
        }
        uniques.append(item);
    }
    return uniques;
}

